import json
rows = [json.loads(l) for l in open('/practice/baseline/original.jsonl')]
def rep_score(t):
    lines=[l for l in t.split('\n') if l.strip()]
    if not lines: return 0
    return sum(1 for i in range(1,len(lines)) if lines[i]==lines[i-1])
cand=[]
for r in rows:
    if r['finish']=='length':
        cand.append((rep_score(r['text']), r['tokens'], r['qid'], r['sample']))
cand.sort(reverse=True)
for c in cand[:15]: print(c)

